-- Adds the 10 old-site trails that were not yet in the catalog, so all 15 live
-- trails from kamatrails.co.il exist as `trails` rows. Content is authored from
-- the old-site scrape (meetings_docs/scrape_old.txt); hero_image/gallery hold
-- relative trip_photos paths (resolved to the public bucket URL at render time).
--
-- price is a placeholder (180) — it is only the catalog default shown on the
-- trail page; the real charge comes from each dated departure's own price, so no
-- one can be charged until an admin publishes a departure. No departures are
-- created here (adding a trail to the catalog is not the same as publishing a
-- bookable date). `on conflict (slug) do nothing` keeps this idempotent and
-- non-destructive to the 5 existing rows.

insert into public.trails (
  slug, name, short_name, region, region_label, difficulty, difficulty_label,
  price, height, duration, hero_image, excerpt, description, gear, audience,
  included, sort_order, gallery
)
select
  x.slug, x.name, x.short_name, x.region, x.region_label, x.difficulty, x.difficulty_label,
  x.price, x.height, x.duration, x.hero_image, x.excerpt, x.description, x.gear, x.audience,
  x.included, x.sort_order,
  coalesce((select array_agg(g) from jsonb_array_elements_text(x.gallery) g), '{}')
from jsonb_to_recordset($json$
